globalCss:
/* Mecha Global Styles */

:root {
  --mecha-navy: #1a2744;
  --mecha-green: #4a5c3a;
  --mecha-yellow: #fbbf24;
  --mecha-red: #ef4444;
}

/* Tech grid background */
.mecha-grid {
  background-image:
    linear-gradient(rgba(74, 92, 58, 0.15) 1px, transparent 1px),
    linear-gradient(90deg, rgba(74, 92, 58, 0.15) 1px, transparent 1px);
  background-size: 40px 40px;
}

/* Warning stripe pattern */
.mecha-warning {
  background: repeating-linear-gradient(
    -45deg,
    var(--mecha-yellow),
    var(--mecha-yellow) 10px,
    var(--mecha-navy) 10px,
    var(--mecha-navy) 20px
  );
}

/* Panel border */
.mecha-panel {
  border: 2px solid var(--mecha-green);
  background: var(--mecha-navy);
  position: relative;
}
.mecha-panel::before {
  content: "";
  position: absolute;
  top: 4px;
  left: 4px;
  right: -4px;
  bottom: -4px;
  border: 1px solid rgba(251, 191, 36, 0.2);
  pointer-events: none;
}

/* Status indicator */
.mecha-status {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: monospace;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--mecha-green);
}
.mecha-status::before {
  content: "";
  width: 8px;
  height: 8px;
  background: var(--mecha-yellow);
}
@keyframes mecha-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes mecha-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.mecha-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(26, 39, 68, 0.08);
}

.mecha-accent-corner {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 2rem), calc(100% - 2rem) 100%, 0 100%);
}

.mecha-animate-in {
  animation: mecha-fade-in 0.5s ease-out both;
}
